      "vi": "Hãy chọn phương án KHÔNG chính xác khi nói về nguyên nhân gây ra đoản mạch (chập điện).",
      "explain": "Đoản mạch (Tanraku) xảy ra khi dòng điện đi tắt qua một con đường có điện trở rất thấp, thường là do hai dây dẫn chạm trực tiếp vào nhau. Các nguyên nhân phổ biến bao gồm đấu nối sai (haisen misu), cắt dây khi vẫn đang có điện (kassen joutai), hoặc do dụng cụ kim loại chạm vào mạch. Ngược lại, khi dây điện được cách điện hoàn toàn (zetsuen), dòng điện sẽ không thể thoát ra ngoài mạch chính để gây chập, do đó đây không thể là nguyên nhân gây đoản mạch.\n\nTừ vựng:\n短絡(たんらく) (Đoản mạch/Chập điện): Hiện tượng dòng điện tăng vọt do nối tắt.\n原因(げんいん) (Nguyên nhân): Lý do dẫn đến sự cố.\n正しい(ただしい) (Chính xác): Đúng đắn.\n選ぶ(えらぶ) (Chọn): Thao tác lựa chọn.\n配線(はいせん)ミス(みす) (Lỗi đi dây): Thao tác nối dây sai quy trình.\n活線状態(かっせんじょうたい) (Trạng thái đang có điện): Mạch điện đang vận hành.\n電線(でんせん) (Dây điện): Dây dẫn năng lượng điện.\n切断(せつだん) (Cắt đứt): Hành động làm đứt rời.\n完全(かんぜん) (Hoàn toàn): Trạng thái triệt để.\n絶縁(ぜつえん) (Cách điện): Ngăn chặn dòng điện rò rỉ.\n工具(こうぐ) (Dụng cụ): Đồ dùng làm việc.\n接触(せっしょく) (Tiếp xúc): Chạm vào nhau.",
      "tip": "💡 Mẹo nhớ: Khi câu hỏi yêu cầu tìm nguyên nhân KHÔNG chính xác (正(ただ)しくない) gây ra sự cố điện, hãy chọn đáp án có các từ tích cực như 完(かん)全(ぜん) (Hoàn toàn) hoặc 絶(ぜつ)縁(えん) (Cách điện)."
