      "explain": "Hoạt động KY (Kiken Yochi - Dự đoán nguy hiểm) là một phần cực kỳ quan trọng trong cuộc họp an toàn trước khi bắt đầu công việc. Mục đích của hoạt động này là để các thành viên cùng thảo luận, nhận diện và dự đoán những nguy hiểm (kiken) có khả năng xảy ra trong quá trình thi công, từ đó đưa ra các biện pháp phòng tránh kịp thời để đảm bảo an toàn tuyệt đối cho công trường.\n\nTừ vựng:\n安全(あんぜん) (An toàn): Trạng thái không có nguy hiểm.\n行う(おこなう) (Thực hiện/Tiến hành): Thực thi một hoạt động.\n活動(かつどう) (Hoạt động): Các việc làm có mục đích.\n内容(ないよう) (Nội dung): Các vấn đề được đề cập.\n作業効率(さぎょうこうりつ) (Hiệu suất công việc): Khả năng hoàn thành việc nhanh.\n上げる(あげる) (Tăng lên): Làm cho cao hơn.\n方法(ほうほう) (Phương pháp): Cách thức thực hiện.\n過去(かこ) (Quá khứ): Thời gian đã qua.\n作業時間(さぎょうじかん) (Thời gian làm việc): Thời lượng thi công.\n見直し(みなおし) (Xem xét lại): Kiểm tra để điều chỉnh.\n作業員(さぎょういん) (Công nhân/Người lao động): Người thực hiện công việc.\n交代(こうたい) (Thay ca/Đổi người): Việc thay thế vị trí làm việc.\n確認(かくにん) (Xác nhận): Kiểm tra để khẳng định.\n予測(よそく) (Dự đoán/Tiên đoán): Đoán trước sự việc sẽ xảy ra.\n危険(きけん) (Nguy hiểm): Mối đe dọa đến an toàn.\n見つける(みつける) (Tìm thấy/Phát hiện): Tìm ra thứ gì đó.",
      "tip": "💡 Mẹo nhớ: Khi thấy cụm từ KY活(かつ)動(どう), hãy chọn ngay đáp án có chứa từ 危(き)険(けん) (Nguy hiểm) và 予(よ)測(そく) (Dự đoán) hoặc 見(み)つける (Tìm thấy)."
