      "explain": "Rò rỉ điện là hiện tượng cực kỳ nguy hiểm có thể dẫn đến giật điện hoặc hỏa hoạn. Để phòng tránh và phát hiện kịp thời, việc lắp đặt thiết bị cảnh báo rò rỉ điện (Rouden keihouki) là biện pháp thiết thực nhất. Thiết bị này sẽ phát hiện dòng điện rò rỉ ra ngoài mạch chính và phát tín hiệu cảnh báo hoặc ngắt mạch để đảm bảo an toàn cho người và công trình.\n\nTừ vựng:\n漏電(ろうでん) (Rò điện): Dòng điện thoát ra ngoài mạch dẫn.\n防止(ぼうし) (Phòng tránh): Ngăn chặn sự cố xảy ra.\n適切(てきせつ) (Phù hợp): Đúng và hiệu quả.\n対策(たいさく) (Đối sách/Biện pháp): Cách giải quyết vấn đề.\n正しい(ただしい) (Chính xác): Đúng đắn.\n選ぶ(えらぶ) (Chọn): Lựa chọn phương án.\n漏電警報器(ろうでんけいほうき) (Thiết bị cảnh báo rò điện): Máy phát tín hiệu khi có rò điện.\n設置(せっち) (Lắp đặt): Đặt thiết bị vào vị trí sử dụng.\n配線(はいせん) (Đi dây/Hệ thống dây điện): Mạng lưới dây dẫn.\n取り除く(とりのぞく) (Loại bỏ): Dọn dẹp hoặc vứt bỏ.\n電流(でんりゅう) (Dòng điện): Luồng điện chạy trong dây.\n増加(ぞうか) (Tăng lên): Làm cho nhiều hơn.\n作業中(さぎょうちゅう) (Trong khi làm việc): Lúc đang thi công.",
      "tip": "💡 Mẹo nhớ: Khi nhắc đến việc đối phó với 漏(ろう)電(でん) (Rò điện), hãy chọn đáp án có chứa các thiết bị bảo vệ như 警(けい)報(ほう)器(き) (Thiết bị cảnh báo) hoặc 遮(しゃ)断(だん)器(き) (Thiết bị ngắt điện)."
