      "explain": "Lỗi hệ thống hoặc lỗi tập thể (shuudan kekkan) thường xảy ra khi áp lực công việc tăng cao, đặc biệt là khi tiến độ thi công (kouki) bị chậm và không kịp hoàn thành đúng hạn. Trong tình trạng vội vã để kịp tiến độ, người lao động dễ bỏ qua các quy trình an toàn hoặc các bước kiểm tra chất lượng quan trọng, dẫn đến việc mắc lỗi hàng loạt hoặc sai sót có tính hệ thống.\n\nTừ vựng:\n集団欠陥(しゅうだんけっかん) (Lỗi tập thể/Lỗi hệ thống): Sai sót xảy ra ở quy mô nhóm.\n発生(はっせい) (Phát sinh): Sự việc nảy sinh hoặc bắt đầu.\n状況(じょうきょう) (Tình huống/Tình trạng): Hoàn cảnh cụ thể.\n正しい(ただしい) (Chính xác): Đúng đắn.\n選ぶ(えらぶ) (Chọn): Thao tác lựa chọn.\n工期(こうき) (Thời hạn thi công): Thời gian quy định để hoàn thành công trình.\n余裕(よゆう) (Dư dả/Thoải mái): Có dư về thời gian hoặc không gian.\n場合(ばあい) (Trường hợp): Tình huống cụ thể.\n事故(じこ) (Tai nạn): Sự cố ngoài ý muốn.\n全員(ぜんいん) (Tất cả mọi người): Toàn bộ thành viên.\n安全行動(あんぜんこうどう) (Hành động an toàn): Các thao tác đúng quy chuẩn.\n間に合う(まにあう) (Kịp thời): Hoàn thành đúng hạn.",
      "tip": "💡 Mẹo nhớ: Khi nhắc đến nguyên nhân gây ra 欠(けっ)陥(かん) (Sai sót/Lỗi), hãy tìm đáp án liên quan đến việc vội vàng do 工(こう)期(き) (Thời hạn thi công) không còn nhiều."
