      "vi": "Kirin Jack (kích cao/kích hươu cao cổ) là dụng cụ được sử dụng với mục đích nào? Hãy chọn một đáp án trong các phương án sau.",
      "explain": "Kirin Jack (Kirin jakki) là một loại kích chuyên dụng có thân cao, thường được sử dụng trong các công trình xây dựng và lắp đặt điện để nâng các vật nặng (omoi mono) theo phương thẳng đứng (suichoku). Nhờ thiết kế đặc biệt, nó có thể hỗ trợ nâng các thiết bị hoặc cấu kiện lên cao một cách ổn định và an toàn tại những vị trí mà các loại kích thông thường không với tới được.\n\nTừ vựng:\n目的(もくてき) (Mục đích): Lý do sử dụng.\n使う(つかう) (Sử dụng): Dùng công cụ.\n器具(きぐ) (Dụng cụ): Đồ dùng hỗ trợ công việc.\n選ぶ(えらぶ) (Chọn): Lựa chọn đáp án.\n重い(おもい) (Nặng): Vật có trọng lượng lớn.\n垂直(すいちょく) (Thẳng đứng): Phương vuông góc với mặt đất.\n持ち上げる(もちあげる) (Nâng lên): Thao tác nhấc vật lên cao.\n軽い(かるい) (Nhẹ): Vật có trọng lượng nhỏ.\n水平(すいへい) (Nằm ngang): Phương song song với mặt đất.\n工具(こうぐ) (Dụng cụ): Đồ dùng làm việc.\n固定(こてい) (Cố định): Giữ chặt vật tại một vị trí.\n作業場(さぎょうじょう) (Nơi làm việc): Khu vực thi công.\n清掃(せいそう) (Dọn dẹp/Vệ sinh): Làm sạch môi trường.",
      "tip": "💡 Mẹo nhớ: Khi nhắc đến キリンジャッキ(きりんじゃっき) (Kích hươu cao cổ), hãy chọn đáp án có từ 重(おも)い(Nặng) và 垂(すい)直(ちょく)(Thẳng đứng) vì hươu cao cổ thường vươn cao lên trời."
