      "explain": "Việc bấm cốt không chặt hoặc bị lỗi (atchaku furyou) làm cho diện tích tiếp xúc giữa dây điện và đầu nối bị giảm đi, dẫn đến điện trở tăng cao tại vị trí đó. Khi có dòng điện chạy qua, điện trở lớn sẽ sinh ra nhiệt lượng lớn gây ra hiện tượng phát nhiệt (hatsunetsu). Nếu nhiệt độ tăng quá cao, nó có thể làm nóng chảy lớp vỏ cách điện và dẫn đến phát hỏa (hakka), gây cháy nổ cực kỳ nguy hiểm cho hệ thống điện.\n\nTừ vựng:\n電線(でんせん) (Dây điện): Dây dẫn năng lượng điện.\n圧着不良(あっちゃくふりょう) (Bấm cốt lỗi): Việc kết nối đầu cốt không đảm bảo kỹ thuật.\n引き起こす(ひきおこす) (Gây ra/Dẫn đến): Làm nảy sinh một sự việc.\n可能性(かのうせい) (Khả năng): Xác suất xảy ra sự việc.\n事故(じこ) (Tai nạn): Sự cố ngoài ý muốn.\n正しい(ただしい) (Chính xác): Đúng đắn.\n電気料金(でんきりょうきん) (Tiền điện): Chi phí sử dụng điện.\n増加(ぞうか) (Tăng lên): Sự nhiều lên về số lượng.\n発熱(はつねつ) (Phát nhiệt): Hiện tượng sinh ra nhiệt.\n発火(はっか) (Phát hỏa): Hiện tượng bắt lửa cháy.\n低電圧(ていでんあつ) (Điện áp thấp): Mức điện áp dưới chuẩn.\n発生(はっせい) (Phát sinh): Sự xuất hiện của sự việc.\n伸び(のび) (Sự giãn dài): Sự tăng về chiều dài vật lý.",
